insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'Even though the experiment was small, its results raised important questions for future research for adult learners, as described in a student guide.','The results were ignored because the experiment was not small.','Despite its limited size, the experiment produced results that future studies should examine.','Future research became unnecessary after the experiment.','The experiment was too large to raise useful questions.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_12", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The passage implies that convenience may encourage people to use a service, but it does not guarantee satisfaction in public institutions, as described in a pilot study.','The passage argues that inconvenient services attract the most users.','The passage denies that convenience affects service use.','The passage suggests that a convenient service can attract users without necessarily satisfying them.','The passage says convenience always guarantees satisfaction.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_12", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The committee approved the plan only after several risks had been identified and addressed during periods of change, as described in a professional workshop.','The committee rejected the plan because all risks were addressed.','The plan was accepted although no risks were identified.','The committee approved the plan before considering any risks.','The plan was accepted once the committee had dealt with the risks it found.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_12", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The decline in complaints was gradual, so managers were careful not to attribute it to a single change in small communities, as described in a policy review.','Because complaints decreased slowly, managers avoided saying that one change alone caused the improvement.','The decline in complaints was sudden and easy to explain.','Managers ignored the decline because it was caused by one change.','Managers blamed a single change because complaints rose quickly.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_12", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The writer contrasts short-term popularity with long-term reliability when resources are limited, as described in a classroom discussion.','The writer says popularity and reliability are exactly the same.','The writer points out a difference between being popular now and being dependable over time.','The writer discusses reliability without mentioning popularity.','The writer argues that long-term reliability is impossible.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_12", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'Although community gardens was initially criticized, later evidence showed that it could be useful when applied carefully under careful supervision, as described in a research summary.','The usefulness of community gardens was accepted before anyone criticized it.','Later evidence showed that community gardens should never be applied.','Later evidence suggested that community gardens, despite early criticism, may have value if used carefully.','Early criticism proved that community gardens had no value at all.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_12", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The report does not claim that health warnings solves every problem; it argues only that it can reduce one specific difficulty after initial trials, as described in a public debate.','The report rejects the idea that health warnings can help in any way.','The report discusses many solutions but never mentions a specific problem.','The report argues that health warnings solves all problems completely.','According to the report, health warnings is not a complete solution but may help with a particular problem.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_12", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The author suggests that frequent practice is effective only when learners receive feedback on their mistakes when resources are limited, as described in a committee meeting in a coastal academic seminar context.','The author believes practice works best if learners are told what they did wrong.','The author suggests that practice and feedback are unrelated.','The author believes mistakes should be ignored during practice.','The author claims feedback is useful only when students stop practicing.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_13", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
