insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The committee approved the plan only after several risks had been identified and addressed for adult learners, as described in a public debate in a urban community college context.','The plan was accepted although no risks were identified.','The plan was accepted once the committee had dealt with the risks it found.','The committee approved the plan before considering any risks.','The committee rejected the plan because all risks were addressed.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_16", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The decline in complaints was gradual, so managers were careful not to attribute it to a single change in public institutions, as described in a training program in a northern community college context.','Managers blamed a single change because complaints rose quickly.','Managers ignored the decline because it was caused by one change.','Because complaints decreased slowly, managers avoided saying that one change alone caused the improvement.','The decline in complaints was sudden and easy to explain.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_16", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The writer contrasts short-term popularity with long-term reliability during periods of change, as described in an evaluation report in a southern community college context.','The writer says popularity and reliability are exactly the same.','The writer argues that long-term reliability is impossible.','The writer discusses reliability without mentioning popularity.','The writer points out a difference between being popular now and being dependable over time.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_16", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'Although automatic translation was initially criticized, later evidence showed that it could be useful when applied carefully in small communities, as described in a committee meeting.','Later evidence suggested that automatic translation, despite early criticism, may have value if used carefully.','Early criticism proved that automatic translation had no value at all.','Later evidence showed that automatic translation should never be applied.','The usefulness of automatic translation was accepted before anyone criticized it.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_16", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The report does not claim that financial education solves every problem; it argues only that it can reduce one specific difficulty when resources are limited, as described in a student guide.','The report discusses many solutions but never mentions a specific problem.','According to the report, financial education is not a complete solution but may help with a particular problem.','The report argues that financial education solves all problems completely.','The report rejects the idea that financial education can help in any way.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_16", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'Researchers postponed their recommendation because the available data were too limited to support a firm conclusion under careful supervision, as described in a pilot study in a evening community college context.','The available data forced the researchers to reject all conclusions.','The researchers postponed collecting data after reaching a firm conclusion.','The researchers delayed giving advice since the evidence was insufficient for a definite conclusion.','The researchers made a recommendation because the data were complete.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_16", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The author suggests that frequent practice is effective only when learners receive feedback on their mistakes after initial trials, as described in a professional workshop in a summer community college context.','The author suggests that practice and feedback are unrelated.','The author claims feedback is useful only when students stop practicing.','The author believes mistakes should be ignored during practice.','The author believes practice works best if learners are told what they did wrong.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_16", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
