insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The report does not claim that sleep tracking solves every problem; it argues only that it can reduce one specific difficulty after initial trials, as described in a pilot study.','The report discusses many solutions but never mentions a specific problem.','The report argues that sleep tracking solves all problems completely.','According to the report, sleep tracking is not a complete solution but may help with a particular problem.','The report rejects the idea that sleep tracking can help in any way.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_17", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Researchers postponed their recommendation because the available data were too limited to support a firm conclusion in schools, as described in a professional workshop.','The researchers postponed collecting data after reaching a firm conclusion.','The available data forced the researchers to reject all conclusions.','The researchers made a recommendation because the data were complete.','The researchers delayed giving advice since the evidence was insufficient for a definite conclusion.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_17", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The author suggests that frequent practice is effective only when learners receive feedback on their mistakes for adult learners, as described in a policy review.','The author believes practice works best if learners are told what they did wrong.','The author believes mistakes should be ignored during practice.','The author claims feedback is useful only when students stop practicing.','The author suggests that practice and feedback are unrelated.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_17", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The new system was adopted not because it was cheaper, but because it made the process more transparent in public institutions, as described in a classroom discussion.','The new system was adopted mainly because it reduced costs.','The main reason for adopting the new system was improved transparency rather than lower cost.','The new system was rejected because it was not transparent.','The process became less transparent after the new system was adopted.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_17", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Even though the experiment was small, its results raised important questions for future research during periods of change, as described in a research summary.','The experiment was too large to raise useful questions.','Future research became unnecessary after the experiment.','Despite its limited size, the experiment produced results that future studies should examine.','The results were ignored because the experiment was not small.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_17", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The passage implies that convenience may encourage people to use a service, but it does not guarantee satisfaction in small communities, as described in a public debate.','The passage says convenience always guarantees satisfaction.','The passage argues that inconvenient services attract the most users.','The passage denies that convenience affects service use.','The passage suggests that a convenient service can attract users without necessarily satisfying them.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_17", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
